using System.Text.Json;
using SunEyeVision.Plugin.Contracts;
using SunEyeVision.Plugin.Runtime;
using SunEyeVision.Plugin.Contracts.Results.Presentation;

var rows=new List<object>();
void Check(bool value,string message){if(!value)throw new Exception(message);}
void Reject(Action action){try{action();}catch(ArgumentException){return;}catch(InvalidOperationException){return;}throw new Exception("Invalid operation was accepted");}
void Test(string name,Action action){try{action();rows.Add(new{name,passed=true});}catch(Exception error){rows.Add(new{name,passed=false,error=error.ToString()});}}
var document=Guid.NewGuid();var node=new BindingNodeId("flow","node");
BindingScopeSnapshot Scope(long revision,Guid? owner=null,BindingNodeId? consumer=null)=>new(consumer??node,owner??document,revision,Array.Empty<BindingSource>(),Array.Empty<BindingNodeId>(),Array.Empty<KeyValuePair<BindingNodeId,IReadOnlyList<BindingNodeId>>>());
var identity=new EditScopeIdentity(document,Guid.NewGuid(),node,0);
var ports=new[]{new Port("value",DataType.Number),new Port("array",DataType.NumberArray,Required:false,Nullable:true)};
ParameterEditSession Session()=>new(ports,new Dictionary<string,ParameterSetting>{{"value",new ConstantSetting(1d)}},new ParameterBindingService(),Scope(0),identity);
PreparedParameterEdit Prepare(ParameterEditSession session){Check(session.TryPrepare(session.Identity!.Value,Scope(session.Identity.Value.BaseConfigurationRevision),out var proposal,out var errors),string.Join(";",errors.Select(e=>e.Message)));return proposal!;}
Test("prepared-constant-copy-on-write-and-read",()=>{var session=Session();var values=new[]{2d,3d};session.Set("array",new ConstantSetting(values));var proposal=Prepare(session);values[0]=7;var first=(double[])((ConstantSetting)proposal.Changes["array"]).Value!;first[0]=8;Check(((double[])((ConstantSetting)proposal.Changes["array"]).Value!)[0]==2,"proposal was mutated");});
Test("wrong-owner-document-node-revision-no-mutation",()=>{var session=Session();session.Set("value",new ConstantSetting(2d));var proposal=Prepare(session);var other=Session();var revision=session.DraftRevision;Reject(()=>other.AcceptPublished(proposal,new Dictionary<string,ParameterSetting>{{"value",new ConstantSetting(2d)}},Scope(1),true));Reject(()=>session.AcceptPublished(proposal,proposal.Changes,Scope(1,Guid.NewGuid()),true));Reject(()=>session.AcceptPublished(proposal,proposal.Changes,Scope(1,consumer:new("flow","other")),true));Reject(()=>session.AcceptPublished(proposal,proposal.Changes,Scope(-1),true));Check(session.DraftRevision==revision&&((ConstantSetting)session.Committed["value"]).Value!.Equals(1d),"rejected receipt mutated session");});
Test("late-ack-retains-new-draft-and-refreshes-baseline",()=>{var session=Session();session.Set("value",new ConstantSetting(2d));var proposal=Prepare(session);session.Set("value",new ConstantSetting(3d));var ack=session.AcceptPublished(proposal,proposal.Changes,Scope(1),true);Check(ack.NewerDraftPreserved&&session.Identity!.Value.BaseConfigurationRevision==1,"late publication baseline not adopted");Check(((ConstantSetting)session.Committed["value"]).Value!.Equals(2d),"published baseline lost");Check(((ConstantSetting)Prepare(session).Changes["value"]).Value!.Equals(3d),"new draft was cleared");});
Test("late-ack-after-cancel-keeps-published-state",()=>{var session=Session();session.Set("value",new ConstantSetting(2d));var proposal=Prepare(session);session.Cancel();session.AcceptPublished(proposal,proposal.Changes,Scope(1),true);Check(Prepare(session).Changes.Count==0&&((ConstantSetting)session.Committed["value"]).Value!.Equals(2d),"cancel rolled back already published transaction");});
Test("late-ack-keeps-invalid-raw",()=>{var session=Session();session.Set("value",new ConstantSetting(2d));var proposal=Prepare(session);session.SetText("value","bad");session.AcceptPublished(proposal,proposal.Changes,Scope(1),true);Check(session.HasInvalidDraft&&!session.TryPrepare(session.Identity!.Value,Scope(1),out _,out _),"late ack erased invalid raw text");});
Test("unset-null-and-validempty-distinct",()=>{var session=Session();session.Clear("array");Check(Prepare(session).Changes["array"] is UnsetSetting,"Clear is not Unset");session.Set("array",new ConstantSetting(null));Check(((ConstantSetting)Prepare(session).Changes["array"]).Value is null,"typed null changed");session.Set("array",new ConstantSetting(Array.Empty<double>()));Check(((double[])((ConstantSetting)Prepare(session).Changes["array"]).Value!).Length==0,"valid empty changed");Check(!session.Clear("value"),"required Unset accepted");});
Test("configuration-change-advances-noop-keeps-revision",()=>{var session=Session();var proposal=Prepare(session);Reject(()=>session.AcceptPublished(proposal,session.Committed,Scope(0),true));session.AcceptPublished(proposal,session.Committed,Scope(0),false);Check(session.Identity!.Value.BaseConfigurationRevision==0,"no-op advanced config");Reject(()=>session.TryCommit());Reject(()=>session.AcceptPublished(proposal,session.Committed,Scope(0),false));});
Test("stale-prepare-scope-rejected",()=>{var session=Session();Check(!session.TryPrepare(identity,Scope(1),out _,out _),"stale config prepared");Check(!session.TryPrepare(identity,Scope(0,Guid.NewGuid()),out _,out _),"wrong document prepared");});
var record=TypeRef.RecordOf("test.row",new[]{new Port("id",DataType.Integer),new Port("value",DataType.Number),new Port("valid",DataType.Boolean)});
var schema=new ToolSchema(Array.Empty<Port>(),new[]{new Port("rows",TypeRef.SequenceOf(record)),new Port("other",TypeRef.SequenceOf(record)),new Port("scalar",DataType.Number)});
ResultProjectionDescriptor Table(params ResultColumnDescriptor[] columns)=>new(ResultProjectionKind.StandardTable,ResultCardinality.Many,columns,new("rows"),"id");
Test("valid-row-identity-and-published-bool",()=>Check(Table(new ResultColumnDescriptor("v","Value",new("rows",new[]{"value"}),ValidWhen:new("rows",new[]{"valid"}))).Validate(schema).Count==0,"valid projection rejected"));
Test("cross-collection-column-rejected",()=>Check(Table(new ResultColumnDescriptor("v","Value",new("other",new[]{"value"}))).Validate(schema).Count>0,"cross rows accepted"));
Test("nonboolean-validity-rejected",()=>Check(Table(new ResultColumnDescriptor("v","Value",new("rows",new[]{"value"}),ValidWhen:new("rows",new[]{"id"}))).Validate(schema).Count>0,"nonbool accepted"));
Test("missing-stable-identity-rejected",()=>Check(new ResultProjectionDescriptor(ResultProjectionKind.StandardTable,ResultCardinality.Many,new[]{new ResultColumnDescriptor("v","Value",new("rows",new[]{"value"}))},new("rows"),"missing").Validate(schema).Count>0,"missing row ID accepted"));
Test("one-row-sequence-cell-rejected",()=>Check(new ResultProjectionDescriptor(ResultProjectionKind.StandardTable,ResultCardinality.One,new[]{new ResultColumnDescriptor("v","Value",new("rows"))}).Validate(schema).Count>0,"sequence treated as one scalar"));
Test("editor-kind-schema-mismatch-rejected",()=>Reject(()=>new ToolSchema(new[]{new Port("value",DataType.Integer)},Array.Empty<Port>(),new ToolPresentation(new[]{new FieldPresentation("value","Value","",0,FieldEditorKind.Geometry)}))));
Test("undeclared-editor-field-rejected",()=>Reject(()=>new ToolSchema(ports,Array.Empty<Port>(),new ToolPresentation(new[]{new FieldPresentation("missing","Value","",0,FieldEditorKind.Scalar)}))));
Test("choice-schema-semantic-fingerprint",()=>{ToolSchema Declare(string label,string[] choices)=>new(new[]{new Port("mode",DataType.Text,Choices:new TextChoiceConstraint(choices))},Array.Empty<Port>(),new ToolPresentation(new[]{new FieldPresentation("mode",label,"",0,FieldEditorKind.Choice,choices)}));Check(Declare("A",new[]{"x","y"}).Fingerprint==Declare("B",new[]{"x","y"}).Fingerprint,"label changed semantics");Check(Declare("A",new[]{"x","y"}).Fingerprint!=Declare("A",new[]{"x","z"}).Fingerprint,"closed choices not fingerprinted");});
Test("choice-direct-constant-and-frozen-input-rejected",()=>{var port=new Port("mode",DataType.Text,Choices:new TextChoiceConstraint(new[]{"x","y"}));var session=new ParameterEditSession(new[]{port},new Dictionary<string,ParameterSetting>());Check(!session.Set("mode",new ConstantSetting("z")),"typed constant escaped choice constraint");Reject(()=>new InputValues(new[]{port},new Dictionary<string,object?>{{"mode","z"}}));});
Test("choice-resolved-reference-runtime-rejected",()=>{var text=TypeRef.ScalarOf(ScalarKind.Text);var source=new BindingNodeId("flow","source");var sourceSchema=new ToolSchema(Array.Empty<Port>(),new[]{new Port("text",text)});var sourceDeclaration=new BindingSource(source,Guid.NewGuid(),sourceSchema,0);var scope=new BindingScopeSnapshot(node,document,0,new[]{sourceDeclaration},new[]{source},Array.Empty<KeyValuePair<BindingNodeId,IReadOnlyList<BindingNodeId>>>());var target=new Port("mode",text,Choices:new TextChoiceConstraint(new[]{"x","y"}));var compiled=new ParameterBindingService().CompileBinding(new("source","text",text,scopeId:"flow"),target,scope);Check(compiled.Plan is not null&&compiled.Compatibility==BindingCompatibility.Conditional,"unproven closed domain was treated as unconditional");var run=Guid.NewGuid();var scopeId=Guid.NewGuid();var sourceIdentity=new RunIdentity(document,run,scopeId,"source",Guid.NewGuid());var consumerIdentity=new RunIdentity(document,run,scopeId,"node",Guid.NewGuid());var snapshot=new BindingRunSnapshot(node,consumerIdentity,0,new[]{new BindingNodeResult(source,sourceIdentity,0,sourceSchema.Fingerprint,true,new InputValues(sourceSchema.Outputs,new Dictionary<string,object?>{{"text","z"}}))},new Dictionary<BindingNodeId,RunIdentity>{{source,sourceIdentity}});Check(!new ParameterBindingService().ResolveBinding(compiled.Plan!,snapshot).Success,"resolved reference escaped choice constraint");});
Console.WriteLine(JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));
return rows.All(row=>JsonSerializer.SerializeToElement(row).GetProperty("passed").GetBoolean())?0:1;
